// Утверждения сделаны в админке 05–06.10 и необратимы (session.json test_data). Только чтение.
import { test, expect } from '@playwright/test';
import * as path from 'path';
import { APPROVED_LINE, UNAPPROVED_LINE, openFragment, saveProgress, restoreProgress } from '../_helpers/prayer-nav';

test.use({ storageState: path.resolve(__dirname, '../../../auth/user1.json') });

test.describe('Молитва по шагам', () => {
  test('GP-07 Утверждённые фрагменты: «מקור: … · אושר על ידי …»; неутверждённый — «הטקסט עדיין לא אושר…» #a5decf4a @prod-safe @mobile', async ({ page }) => {
    const saved = await saveProgress(page);
    try {
      // 2. ערבית אשכנז «3 מתוך 15» «המעריב ערבים».
      const n = await openFragment(page, 'arvit_ashkenaz', 3);
      expect(n).toBe(15);
      await expect(page.getByText(APPROVED_LINE), 'arvit_ashkenaz 3/15').toBeVisible();
      await expect(page.getByText(UNAPPROVED_LINE)).toHaveCount(0);

      // 3. סדר אזכרה אשכנז, фрагмент 1.
      await openFragment(page, 'azkara_ashkenaz', 1);
      await expect(page.getByText(APPROVED_LINE), 'azkara_ashkenaz 1').toBeVisible();
      await expect(page.getByText(UNAPPROVED_LINE)).toHaveCount(0);

      // 4. תהילים קי״ז и ל״ט.
      for (const [chapter, title] of [['117', 'תהילים קי״ז'], ['39', 'תהילים ל״ט']]) {
        await page.goto(`/tehilim/${chapter}`);
        await expect(page.getByRole('heading', { level: 1, name: title })).toBeVisible({ timeout: 20_000 });
        await expect(page.getByText(APPROVED_LINE), `tehilim ${chapter}`).toBeVisible();
        await expect(page.getByText(UNAPPROVED_LINE)).toHaveCount(0);
      }

      // 5. בורא פרי הגפן / העץ אשכנז.
      for (const key of ['beracha_hagefen_ashkenaz', 'beracha_haetz_ashkenaz']) {
        await openFragment(page, key, 1);
        await expect(page.getByText(APPROVED_LINE), key).toBeVisible();
        await expect(page.getByText(UNAPPROVED_LINE)).toHaveCount(0);
      }

      // 6. מנחה ספרד — не утверждено.
      await openFragment(page, 'mincha_sfarad', 1);
      await expect(page.getByText(UNAPPROVED_LINE), 'mincha_sfarad 1/11').toBeVisible();
      await expect(page.getByText(/אושר על ידי/)).toHaveCount(0);
    } finally {
      await restoreProgress(page, saved);
    }
  });
});
